    Enum.reject(
      [
        if XP.ebv([XP.ebv(F.not_(doc, v_isau)) or XP.ebv(v_hastxdnote)]) do
          nil
        else
          %{
            type: :assert,
            rule: "BR-FR-CO-14_BT-29-1",
            flag: "warning",
            message:
              XP.message([
                "\n        BR-FR-CO-14/BT-29-1 : Si le schéma d’identification du vendeur (BT-29-1) est '0231', cela signifie qu’il est membre d’un assujetti unique.\n        Dans ce cas, une note (BG-1) avec le code sujet 'TXD' (BT-21) et le texte 'MEMBRE_ASSUJETTI_UNIQUE' (BT-22) doit être présente.\n      "
              ]),
            node: XP.node_path(doc, ctx_id)
          }
        end
      ],
      &is_nil/1
    )
