  defp pattern_36_br_fr_co_15(doc, globals) do
    set_0 =
      XP.match_set(
        XP.step(
          doc,
          XP.step(doc, XP.root(doc), :descendant_or_self, :node, []),
          :child,
          {:name, "urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100", "CrossIndustryInvoice"},
          []
        )
      )

    Enum.flat_map(XP.all_node_ids(doc), fn node_id ->
      cond do
        MapSet.member?(set_0, node_id) ->
          pattern_36_br_fr_co_15_rule_0(doc, globals, {:node, node_id})

        true ->
          []
      end
    end)
  end

  defp pattern_36_br_fr_co_15_rule_0(doc, globals, {:node, ctx_id} = ctx) do
    _ = {doc, globals, ctx_id, ctx}

    v_isau = [
      Enum.any?(
        XP.step(
          doc,
          XP.step(
            doc,
            XP.step(
              doc,
              XP.step(
                doc,
                [ctx],
                :child,
                {:name, "urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100", "SupplyChainTradeTransaction"},
                []
              ),
              :child,
              {:name, "urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100",
               "ApplicableHeaderTradeAgreement"},
              []
            ),
            :child,
            {:name, "urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100", "SellerTradeParty"},
            []
          ),
          :child,
          {:name, "urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100", "GlobalID"},
          []
        ),
        fn quant_id ->
          XP.ebv(
            XP.general_cmp(
              doc,
              :eq,
              XP.step(doc, [quant_id], :attribute, {:name, nil, "schemeID"}, []),
              ["0231"]
            )
          )
        end
      )
    ]

    v_fiscalrep =
      XP.step(
        doc,
        XP.step(
          doc,
          XP.step(
            doc,
            [ctx],
            :child,
            {:name, "urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100", "SupplyChainTradeTransaction"},
            []
          ),
          :child,
          {:name, "urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100",
           "ApplicableHeaderTradeAgreement"},
          []
        ),
        :child,
        {:name, "urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100",
         "SellerTaxRepresentativeTradeParty"},
        []
      )

    v_fiscalvat =
      XP.step(
        doc,
        XP.step(
          doc,
          v_fiscalrep,
          :child,
          {:name, "urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100", "SpecifiedTaxRegistration"},
          []
        ),
        :child,
        {:name, "urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100", "ID"},
        [
          fn pred_item, pred_position, pred_size ->
            _ = {pred_item, pred_position, pred_size}

            XP.general_cmp(
              doc,
              :eq,
              XP.step(doc, [pred_item], :attribute, {:name, nil, "schemeID"}, []),
              ["VA"]
            )
          end
        ]
      )

    _ = {v_isau, v_fiscalrep, v_fiscalvat}

    Enum.reject(
      [
        if XP.ebv([
             XP.ebv(F.not_(doc, v_isau)) or
               XP.ebv([
                 XP.ebv(F.exists(doc, v_fiscalrep)) and XP.ebv(F.string_(doc, v_fiscalvat))
               ])
           ]) do
          nil
        else
          %{
            type: :assert,
            rule: "BR-FR-CO-15_BT-29-1",
            flag: "warning",
            message:
              XP.message([
                "\n        BR-FR-CO-15/BT-29-1 : Si le vendeur est membre d’un assujetti unique (BT-29-1 = 0231), alors le bloc représentant fiscal (BG-11) doit être présent et contenir le numéro de TVA de l’assujetti unique (BT-63).\n        État actuel : représentant fiscal ",
                XP.value_of(
                  doc,
                  if XP.ebv(F.exists(doc, v_fiscalrep)) do
                    ["présent"]
                  else
                    ["absent"]
                  end
                ),
                ", numéro de TVA = \"",
                XP.value_of(doc, v_fiscalvat),
                "\".\n      "
              ]),
            node: XP.node_path(doc, ctx_id)
          }
        end
      ],
      &is_nil/1
    )
  rescue
    error in [ExSchematron.Runtime.Error] ->
      [
        %{
          type: :error,
          rule: "rsm:CrossIndustryInvoice",
          flag: nil,
          message: Exception.message(error),
          node: XP.node_path(doc, ctx_id)
        }
      ]
  end

