                         ),
                         :child,
                         {:name, "urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100",
                          "SpecifiedLineTradeSettlement"},
                         []
                       ),
                       :child,
                       {:name, "urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100",
                        "AdditionalReferencedDocument"},
                       [
                         fn pred_item, pred_position, pred_size ->
                           _ = {pred_item, pred_position, pred_size}

                           [
                             XP.ebv(
