  defp pattern_52_br_fr_mv_13(doc, globals) do
    set_0 =
      XP.match_set(
        XP.step(
          doc,
          XP.step(
            doc,
            XP.step(
              doc,
              XP.step(doc, XP.root(doc), :descendant_or_self, :node, []),
              :child,
              {:name, "urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100", "CrossIndustryInvoice"},
              []
            ),
            :child,
            {:name, "urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100", "ExchangedDocument"},
            []
          ),
          :child,
          {:name, "urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100", "TypeCode"},
          []
        )
      )

    Enum.flat_map(XP.all_node_ids(doc), fn node_id ->
      cond do
        MapSet.member?(set_0, node_id) ->
          pattern_52_br_fr_mv_13_rule_0(doc, globals, {:node, node_id})

        true ->
          []
      end
    end)
  end

  defp pattern_52_br_fr_mv_13_rule_0(doc, globals, {:node, ctx_id} = ctx) do
    _ = {doc, globals, ctx_id, ctx}
    _ = {}

    Enum.reject(
      [
        if XP.ebv([
             XP.ebv(
               F.not_(
                 doc,
                 fn_custom_isspecialcontract(
                   doc,
                   XP.step(
                     doc,
                     XP.root(doc),
                     :child,
                     {:name, "urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100", "CrossIndustryInvoice"},
                     []
                   )
                 )
               )
             ) or
               XP.ebv([
                 XP.ebv(XP.general_cmp(doc, :ne, F.normalize_space(doc, [ctx]), [""])) and
                   XP.ebv(
                     F.not_(doc, [
                       XP.ebv(XP.general_cmp(doc, :eq, [ctx], ["389"])) or
                         XP.ebv([
                           XP.ebv(XP.general_cmp(doc, :eq, [ctx], ["261"])) or
                             XP.ebv([
                               XP.ebv(XP.general_cmp(doc, :eq, [ctx], ["501"])) or
                                 XP.ebv([
                                   XP.ebv(XP.general_cmp(doc, :eq, [ctx], ["500"])) or
                                     XP.ebv([
                                       XP.ebv(XP.general_cmp(doc, :eq, [ctx], ["502"])) or
                                         XP.ebv([
                                           XP.ebv(XP.general_cmp(doc, :eq, [ctx], ["471"])) or
                                             XP.ebv(XP.general_cmp(doc, :eq, [ctx], ["473"]))
                                         ])
                                     ])
                                 ])
                             ])
                         ])
                     ])
                   )
               ])
           ]) do
          nil
        else
          %{
            type: :assert,
            rule: "BR-FR-MV-13_BT-3",
            flag: "fatal",
            message:
              XP.message([
                "\n        BR-FR-MV-13/BT-3 : Lorsque le cadre de facturation (BT-23) est S8, B8 ou M8, le code type de facture (ram:TypeCode) ne doit pas être l'un des types auto-facturés suivants : 389, 261, 501, 500, 502, 471, 473. Valeur actuelle : \"",
                XP.value_of(doc, [ctx]),
                "'.\n      "
              ]),
            node: XP.node_path(doc, ctx_id)
          }
        end
      ],
      &is_nil/1
    )
  rescue
    error in [ExSchematron.Runtime.Error] ->
      [
        %{
          type: :error,
          rule: "rsm:CrossIndustryInvoice/rsm:ExchangedDocument/ram:TypeCode",
          flag: nil,
