  end

  defp fn_custom_is_valid_id_format(doc, v_id) do
    _ = {doc, v_id}
    _ = {}

    [
      XP.ebv(F.matches(doc, F.normalize_space(doc, v_id), ["^[A-Za-z0-9+\\-_/]+$"])) and
        XP.ebv([
          XP.ebv(F.not_(doc, F.matches(doc, v_id, [" "]))) and
            XP.ebv([
              XP.ebv(F.not_(doc, F.starts_with(doc, v_id, [" "]))) and
                XP.ebv(F.not_(doc, F.ends_with(doc, v_id, [" "])))
            ])
        ])
    ]
  end

  defp fn_custom_is_valid_date_format(doc, v_date) do
    _ = {doc, v_date}
    v_shortdate = F.substring(doc, v_date, [1], ~c"\b")

    v_isformatvalid =
      F.matches(doc, v_shortdate, ["^20\\d{2}(0[1-9]|1[0-2])(0[1-9]|[12]\\d|3[01])$"])

    v_year = F.number(doc, F.substring(doc, v_shortdate, [1], [4]))
    v_month = F.number(doc, F.substring(doc, v_shortdate, [5], [2]))
    v_day = F.number(doc, F.substring(doc, v_shortdate, ~c"\a", [2]))

    v_isleapyear = [
      XP.ebv([
        XP.ebv(XP.general_cmp(doc, :eq, XP.arith(doc, :mod, v_year, [4]), [0])) and
          XP.ebv(XP.general_cmp(doc, :ne, XP.arith(doc, :mod, v_year, ~c"d"), [0]))
      ]) or XP.ebv(XP.general_cmp(doc, :eq, XP.arith(doc, :mod, v_year, [400]), [0]))
    ]

    v_maxday =
      if XP.ebv(
           XP.general_cmp(
             doc,
             :eq,
             v_month,
             Enum.concat([[1], [3], [5], ~c"\a", ~c"\b", ~c"\n", ~c"\f"])
           )
         ) do
        [31]
      else
        if XP.ebv(XP.general_cmp(doc, :eq, v_month, Enum.concat([[4], [6], ~c"\t", ~c"\v"]))) do
          [30]
        else
          if XP.ebv([XP.ebv(XP.general_cmp(doc, :eq, v_month, [2])) and XP.ebv(v_isleapyear)]) do
            [29]
          else
            if XP.ebv(XP.general_cmp(doc, :eq, v_month, [2])) do
              [28]
            else
              [0]
            end
          end
        end
      end

    _ = {v_shortdate, v_isformatvalid, v_year, v_month, v_day, v_isleapyear, v_maxday}
    [XP.ebv(v_isformatvalid) and XP.ebv(XP.value_cmp(doc, :le, v_day, v_maxday))]
  end

