  defp fn_custom_isspecialcontract(doc, v_context) do
    _ = {doc, v_context}
    _ = {}

    [
      XP.ebv(
        F.exists(
          doc,
          XP.step(
            doc,
            XP.step(
              doc,
              XP.step(
                doc,
                v_context,
                :child,
                {:name, "urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100", "ExchangedDocumentContext"},
                []
              ),
              :child,
              {:name, "urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100",
               "BusinessProcessSpecifiedDocumentContextParameter"},
              []
            ),
            :child,
            {:name, "urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100", "ID"},
            []
          )
        )
      ) and
        XP.ebv([
          XP.ebv(
            XP.general_cmp(
              doc,
              :eq,
              XP.step(
                doc,
                XP.step(
                  doc,
                  XP.step(
                    doc,
                    v_context,
                    :child,
                    {:name, "urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100", "ExchangedDocumentContext"},
                    []
                  ),
                  :child,
                  {:name, "urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100",
                   "BusinessProcessSpecifiedDocumentContextParameter"},
                  []
                ),
                :child,
                {:name, "urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100", "ID"},
                []
              ),
              ["S8"]
            )
          ) or
            XP.ebv([
              XP.ebv(
                XP.general_cmp(
                  doc,
                  :eq,
                  XP.step(
                    doc,
                    XP.step(
                      doc,
                      XP.step(
                        doc,
                        v_context,
                        :child,
                        {:name, "urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100", "ExchangedDocumentContext"},
                        []
                      ),
                      :child,
                      {:name, "urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100",
                       "BusinessProcessSpecifiedDocumentContextParameter"},
                      []
                    ),
                    :child,
                    {:name, "urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100", "ID"},
                    []
                  ),
                  ["B8"]
                )
              ) or
                XP.ebv(
                  XP.general_cmp(
                    doc,
                    :eq,
                    XP.step(
                      doc,
                      XP.step(
                        doc,
                        XP.step(
                          doc,
                          v_context,
                          :child,
                          {:name, "urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100", "ExchangedDocumentContext"},
                          []
                        ),
                        :child,
